-- An online shop: a tree of categories, products with jsonb attributes and text[] tags, customers, orders and
-- their items, payments, and reviews with jsonb details, made up for Kwery.

create table category (
  category_id integer primary key,
  name varchar(30) not null unique,
  parent_id integer references category (category_id)
);
create table product (
  product_id integer primary key,
  name varchar(60) not null unique,
  category_id integer not null references category (category_id),
  price numeric(10,2) not null check (price > 0),
  attrs jsonb not null default '{}',
  tags text[] not null default '{}'
);
create table customer (
  customer_id integer primary key,
  name varchar(40) not null,
  email varchar(60) not null unique,
  city varchar(30),
  joined date not null
);
create table orders (
  order_id integer primary key,
  customer_id integer not null references customer (customer_id),
  ordered_at timestamp not null,
  status varchar(10) not null check (status in ('pending', 'paid', 'shipped', 'delivered', 'cancelled', 'returned'))
);
create table order_item (
  order_id integer references orders (order_id) on delete cascade,
  line_no smallint check (line_no > 0),
  product_id integer not null references product (product_id),
  quantity integer not null check (quantity > 0),
  unit_price numeric(10,2) not null check (unit_price >= 0),
  primary key (order_id, line_no)
);
create table payment (
  payment_id integer primary key,
  order_id integer not null references orders (order_id),
  paid_at timestamp not null,
  amount numeric(10,2) not null check (amount > 0),
  method varchar(8) not null check (method in ('card', 'transfer', 'wallet'))
);
create table review (
  review_id integer primary key,
  product_id integer not null references product (product_id),
  customer_id integer not null references customer (customer_id),
  rating smallint not null check (rating between 1 and 5),
  title varchar(40),
  created_at timestamp not null,
  details jsonb,
  unique (product_id, customer_id)
);

